int licznik = 0;
int liczba = 0;
int minimum = 1023; // Inicjalizacja bezpieczną maksymalną wartością ADC
int maksimum = 0;   // Inicjalizacja bezpieczną minimalną wartością ADC
int jasnosc = 0;

void Znak(int iNumer) {
  // Sterowanie pinem 8 (np. kropka dziesiętna lub starszy bit)
  digitalWrite(8, ((iNumer == 0) || (iNumer == 1) || (iNumer == 7)) ? HIGH : LOW);
  switch (iNumer) {
    case 0:  PORTD = 0b00000000; break;
    case 1:  PORTD = 0b11100100; break;
    case 2:  PORTD = 0b11000000; break;
    case 3:  PORTD = 0b11110000; break; // Przykładowe uzupełnienie
    default: PORTD = 0b11011000; break;
  }
}

void setup() {
  for (int i = 2; i < 9; i++) {
    pinMode(i, OUTPUT);
  }
  pinMode(10, OUTPUT);
  pinMode(11, OUTPUT);
  delay(1000);

  // Pierwszy pomiar inicjalizujący zakres
  int odczyt = analogRead(0);
  minimum = odczyt;
  maksimum = odczyt;
}

void loop() {
  // Multipleksowanie wyświetlacza (wyświetlanie cyfry jedności i dziesiątek)
  digitalWrite(11, LOW);
  Znak(liczba % 10);
  digitalWrite(10, HIGH);
  delay(2);
  digitalWrite(10, LOW);
  Znak((liczba / 10) % 10);
  digitalWrite(11, HIGH);
  delay(2);

  // Co ok. 100 cykli pętli (ok. 400ms) aktualizujemy odczyt z czujnika
  if (licznik++ > 100) {
    int surowaJasnosc = analogRead(0);

    if (minimum > surowaJasnosc) minimum = surowaJasnosc;
    if (maksimum < surowaJasnosc) maksimum = surowaJasnosc;

    // Przeskalowanie wartości do zakresu 0 - 99
    if (minimum != maksimum) {
      jasnosc = (99L * (surowaJasnosc - minimum)) / (maksimum - minimum);
    } else {
      jasnosc = 0;
    }

    liczba = jasnosc; // Przypisanie przeskalowanej wartości do zmiennej wyświetlanej
    licznik = 0;
  }
}
